                        "time": float(row["time"]),
                        "kind": evt,
                        "entities": [row["task"]],
                        "value": None,
                        "src": [[node_id, idx, ["time", "task", "event", "machine"]]]
                    })

        elif "Queue at window end" in title:
            for idx, row in table_rows(node):
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "remaining_run_time",
                    "entities": [row["task"]],
                    "value": float(row["remaining"]),
                    "src": [[node_id, idx, ["task", "remaining"]]]
                })
    return outcomes_list

def params(doc, scope):
    return {"window_length": 1200.0, "num_machines": 8.0}


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if start is None:
        start = 0.0

    machines = {}
    submissions = []
    for inp in inputs:
        if inp["kind"] == "machine_config":
            m_id = inp["entities"][0]
            machines[m_id] = {
                "cpu": inp["fields"]["CPU"],
                "memory": inp["fields"]["memory"],
                "fails_at": inp["fields"]["fails_at"],
                "returns_at": inp["fields"]["returns_at"]
            }
        elif inp["kind"] == "task_submit":
            t_id = inp["entities"][0]
            submissions.append({
                "time": inp["time"],
                "task": t_id,
                "job": inp["fields"]["job"],
                "priority": int(inp["fields"]["priority"]),
                "cpu": inp["fields"]["CPU"],
                "memory": inp["fields"]["memory"],
                "run_time": inp["fields"]["run_time"]
            })
    submissions.sort(key=lambda x: x["time"])

    task_info = {sub["task"]: sub for sub in submissions}

    machine_state = {}
    for m_id, cfg in machines.items():
        machine_state[m_id] = {
            "up": True,
            "free_cpu": cfg["cpu"],
            "free_mem": cfg["memory"],
            "tasks": []
        }

    fail_schedule = {}
    return_schedule = {}
    for m_id, cfg in machines.items():
        if cfg["fails_at"] is not None and cfg["fails_at"] <= horizon:
            fail_schedule.setdefault(cfg["fails_at"], []).append(m_id)
        if cfg["returns_at"] is not None and cfg["returns_at"] <= horizon:
            return_schedule.setdefault(cfg["returns_at"], []).append(m_id)

    finish_schedule = {}
    waiting = []
    running = {}
    sub_idx = 0
    outcomes = []

    def queue_key(t_id):
        info = task_info[t_id]
        return (-info["priority"], info["time"], int(t_id[1:]))

    def start_task(t_id, m_id, ct):
        info = task_info[t_id]
        ms = machine_state[m_id]
        ms["free_cpu"] -= info["cpu"]
        ms["free_mem"] -= info["memory"]
        ft = ct + info["run_time"]
        ms["tasks"].append((t_id, info["cpu"], info["memory"], ct, ft))
        finish_schedule.setdefault(ft, []).append(t_id)
        running[t_id] = {"machine": m_id, "finish_time": ft, "started": ct}
        outcomes.append({"time": ct, "kind": "start", "entities": [t_id], "value": None, "src": []})

    def remove_from_finish(t_id):
        if t_id in running:
            ft = running[t_id]["finish_time"]
            if ft in finish_schedule and t_id in finish_schedule[ft]:
                finish_schedule[ft].remove(t_id)
                if not finish_schedule[ft]:
                    del finish_schedule[ft]

    def compute_earliest_start(t_id, m_id, ct):
        info = task_info[t_id]
        ms = machine_state[m_id]
        if ms["free_cpu"] >= info["cpu"] and ms["free_mem"] >= info["memory"]:
            return ct
        events = sorted([(ft, cpu, mem) for tid, cpu, mem, st, ft in ms["tasks"]])
        tc, tm = ms["free_cpu"], ms["free_mem"]
        for ft, cpu, mem in events:
            tc += cpu; tm += mem
            if tc >= info["cpu"] and tm >= info["memory"]:
                return ft
        return float('inf')

    def compute_remaining_at_reservation(res_m, res_t, res_task):
        ms = machine_state[res_m]
        rc, rm = machines[res_m]["cpu"], machines[res_m]["memory"]
        for tid, cpu, mem, st, ft in ms["tasks"]:
            if ft > res_t:
                rc -= cpu; rm -= mem
        ri = task_info[res_task]
        rc -= ri["cpu"]; rm -= ri["memory"]
        return (rc, rm)

    current_time = 0.0
    while True:
        next_times = set()
        for sub in submissions[sub_idx:]:
            if sub["time"] <= horizon:
                next_times.add(sub["time"])
        for t in list(fail_schedule.keys()):
            if current_time < t <= horizon:
                next_times.add(t)
        for t in list(return_schedule.keys()):
            if current_time < t <= horizon:
                next_times.add(t)
        for t in list(finish_schedule.keys()):
            if current_time < t <= horizon:
                next_times.add(t)
        next_times = {t for t in next_times if t > current_time}
        if not next_times:
            break
        next_time = min(next_times)
        if next_time > horizon:
            break
        current_time = next_time
        reservation = None

        # Step 1: Finishes (by task id)
        if current_time in finish_schedule:
            for t_id in sorted(finish_schedule[current_time]):
                if t_id not in running:
                    continue
                outcomes.append({"time": current_time, "kind": "finish", "entities": [t_id], "value": None, "src": []})
                m_id = running[t_id]["machine"]
                info = task_info[t_id]
                ms = machine_state[m_id]
                ms["free_cpu"] += info["cpu"]
                ms["free_mem"] += info["memory"]
                ms["tasks"] = [(tid,c,m,st,ft) for tid,c,m,st,ft in ms["tasks"] if tid != t_id]
                del running[t_id]
            del finish_schedule[current_time]

        # Step 2: Failures (by machine, then task id)
        if current_time in fail_schedule:
            for m_id in sorted(fail_schedule[current_time]):
                machine_state[m_id]["up"] = False
                tasks = sorted(machine_state[m_id]["tasks"], key=lambda x: x[0])
                for tid, cpu, mem, st, ft in tasks:
                    outcomes.append({"time": current_time, "kind": "fail", "entities": [tid], "value": None, "src": []})
                    waiting.append(tid)
                    remove_from_finish(tid)
                    if tid in running:
                        del running[tid]
                machine_state[m_id]["tasks"] = []
                machine_state[m_id]["free_cpu"] = 0
                machine_state[m_id]["free_mem"] = 0
            del fail_schedule[current_time]

        # Step 3: Returns
        if current_time in return_schedule:
            for m_id in return_schedule[current_time]:
                machine_state[m_id]["up"] = True
                machine_state[m_id]["free_cpu"] = machines[m_id]["cpu"]
                machine_state[m_id]["free_mem"] = machines[m_id]["memory"]
                machine_state[m_id]["tasks"] = []
            del return_schedule[current_time]

        # Step 4: Submissions
        while sub_idx < len(submissions) and submissions[sub_idx]["time"] == current_time:
            waiting.append(submissions[sub_idx]["task"])
            sub_idx += 1

        # Step 5: Scheduling round
        waiting.sort(key=queue_key)
        seen_set = set()
        waiting = [t for t in waiting if not (t in seen_set or seen_set.add(t))]

        started_this_round = set()
        processed_this_round = set()
        still_waiting = []

        while waiting:
            if all(t in processed_this_round for t in waiting):
                break
            waiting.sort(key=queue_key)
            t_id = waiting[0]
            waiting.pop(0)
            if t_id in started_this_round:
                continue
            processed_this_round.add(t_id)
            info = task_info[t_id]
            is_prod = info["priority"] >= 9
            started = False

            # a: First fit
            for m_id in sorted(machine_state.keys()):
                ms = machine_state[m_id]
                if not ms["up"]:
                    continue
                if ms["free_cpu"] < info["cpu"] or ms["free_mem"] < info["memory"]:
                    continue
                if reservation is not None:
                    r_task, r_time, r_mach = reservation
                    if m_id == r_mach:
                        if current_time + info["run_time"] <= r_time:
                            pass
                        else:
                            rem = compute_remaining_at_reservation(r_mach, r_time, r_task)
                            if info["cpu"] > rem[0] or info["memory"] > rem[1]:
                                continue
                start_task(t_id, m_id, current_time)
                started_this_round.add(t_id)
                started = True
                break
            if started:
                continue

            # b: Preemption
            if is_prod and reservation is None:
                for m_id in sorted(machine_state.keys()):
                    ms = machine_state[m_id]
                    if not ms["up"]:
                        continue
                    ftt = [(tid,cpu,mem,st,ft) for tid,cpu,mem,st,ft in ms["tasks"]
                           if task_info[tid]["priority"] <= 1]
                    ftt.sort(key=lambda x: (task_info[x[0]]["priority"], -x[3], -int(x[0][1:])))
                    tc, tm = ms["free_cpu"], ms["free_mem"]
                    evictions = []
                    for tid, cpu, mem, st, ft in ftt:
                        tc += cpu; tm += mem
                        evictions.append((tid, cpu, mem))
                        if tc >= info["cpu"] and tm >= info["memory"]:
                            break
                    if tc >= info["cpu"] and tm >= info["memory"]:
                        for ev_t, ev_c, ev_m in evictions:
                            outcomes.append({"time": current_time, "kind": "evict", "entities": [ev_t], "value": None, "src": []})
                            ms["free_cpu"] += ev_c; ms["free_mem"] += ev_m
                            ms["tasks"] = [(tid2,c2,m2,st2,ft2) for tid2,c2,m2,st2,ft2 in ms["tasks"] if tid2 != ev_t]
                            remove_from_finish(ev_t)
                            if ev_t in running:
                                del running[ev_t]
                            waiting.append(ev_t)
                        start_task(t_id, m_id, current_time)
                        started_this_round.add(t_id)
                        started = True
                        break
            if started:
                continue

            # c: Reservation
            if reservation is None:
                fits_any = False
                for m_id in sorted(machine_state.keys()):
                    ms = machine_state[m_id]
                    if not ms["up"]:
                        continue
                    if machines[m_id]["cpu"] >= info["cpu"] and machines[m_id]["memory"] >= info["memory"]:
                        fits_any = True; break
                if fits_any:
                    best_t, best_m = float('inf'), None
                    for m_id in sorted(machine_state.keys()):
                        ms = machine_state[m_id]
                        if not ms["up"]:
                            continue
                        if machines[m_id]["cpu"] < info["cpu"] or machines[m_id]["memory"] < info["memory"]:
                            continue
                        earliest = compute_earliest_start(t_id, m_id, current_time)
                        if earliest < best_t:
                            best_t = earliest; best_m = m_id
                    if best_m is not None:
                        reservation = (t_id, best_t, best_m)

            still_waiting.append(t_id)
        waiting = still_waiting

    # remaining_run_time outcomes
    for t_id in sorted(running.keys(), key=lambda x: queue_key(x)):
        st = running[t_id]
        rem = st["finish_time"] - horizon
        if rem > 0:
            outcomes.append({"time": horizon, "kind": "remaining_run_time", "entities": [t_id], "value": rem, "src": []})
    for t_id in sorted(waiting, key=lambda x: queue_key(x)):
        info = task_info[t_id]
        outcomes.append({"time": horizon, "kind": "remaining_run_time", "entities": [t_id], "value": info["run_time"], "src": []})

    return [o for o in outcomes if o["time"] > start]
